/**
 * Reads SQL files from the migrations directory and logs each filename
 * in the order they would be applied
 */
function runMigration() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Migrations directory not found: ${migrationsDir}`);
      process.exit(1);
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter to only include SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Natural sort for numbered filenames

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in', migrationsDir);
      return;
    }

    console.log(`Found ${sqlFiles.length} migration(s) to apply:`);

    // Log each filename it would apply, in order
