    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply in order.
 */

// Path to migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads and returns sorted SQL migration files from the migrations directory
 * @returns {Promise<string[]>} Array of migration filenames sorted by name
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.review(migrationsDir, (err, files) => {
      if (err) {
        if (err.code === 'ENOENT') {
          console.error(`Migrations directory not found: ${migrationsDir}`);
          resolve([]);
        } else {
          reject(err);
        }
        return;
      }

      // Filter for SQL files only and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // Sort alphabetically to ensure proper order

      resolve(sqlFiles);
    });
  });
}

/**
 * Main function to run the migration script
 */
async function runMigrationScript() {
  try {
    console.log('Starting database migration process...');
    console.log(`Reading migration files from: ${migrationsDir}\n`);

    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each filename that would be applied, in order
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. Would apply: ${file}`);
    });

    console.log('\nMigration process completed (dry run - no actual migrations applied).');
  } catch (error) {
    console.error('Error running migration script:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrationScript();

