const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

// Path to migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads all SQL files from the migrations directory and returns them sorted by filename
 * @returns {Promise<string[]>} Array of migration filenames in order
 */
async function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Migrations directory not found: ${migrationsDir}`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for only .sql files
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort files by name (assuming they're prefixed with numbers for ordering)
    const sortedFiles = sqlFiles.sort();

    return sortedFiles;
  } catch (error) {
    console.error('Error reading migration files:', error.message);
    return [];
  }
}

/**
 * Main function to run the migration script
 */
async function runMigration() {
  console.log('Starting database migration...');
  console.log(`Looking for migrations in: ${migrationsDir}`);

  // Get the migration files
  const migrationFiles = await getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):`);

  // Log each filename it would apply, in order
  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. Would apply: ${file}`);
  });

  console.log('Migration process completed.');
}

// Run the migration script
runMigration().catch(error => {
  console.error('Migration script failed:', error.message);
  process.exit(1);
});

