    sqlFiles.sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

/**
 * Reads DATABASE_URL from .env.test file
 * @returns {string|null} DATABASE_URL or null if not found/error
 */
function getDatabaseUrl() {
  try {
    // Check if .env.test file exists
    if (!fs.existsSync(envFilePath)) {
      console.warn(`.env.test file not found: ${envFilePath}`);
      return null;
    }

    // Read the .env.test file
    const envContent = fs.readFileSync(envFilePath, 'utf8');

    // Parse DATABASE_URL from the file content
    const lines = envContent.split('\n');
    for (const line of lines) {
      const trimmedLine = line.trim();
      if (trimmedLine.startsWith('DATABASE_URL=')) {
        return trimmedLine.substring('DATABASE_URL='.length);
      }
    }

    console.warn('DATABASE_URL not found in .env.test file');
    return null;
  } catch (error) {
    console.error('Error reading .env.test file:', error.message);
