const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads migration files from the migrations directory
 * @returns {Promise<Array<string>>} Sorted array of migration filenames
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.reviewDir(migrationsDir, (err, files) => {
      if (err) {
        if (err.code === 'ENOENT') {
          console.log(`Migrations directory not found: ${migrationsDir}`);
          resolve([]);
          return;
        }
        reject(err);
        return;
      }

      // Filter only .sql files and sort them
      const migrationFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // This will sort numerically if files are prefixed with numbers

      resolve(migrationFiles);
    });
  });
}

/**
 * Logs each migration file that would be applied
 */
async function logMigrations() {
  try {
    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s) to apply:`);
