const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

// Path to migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads and returns SQL migration files in sorted order
 * @returns {string[]} Array of migration filenames in order
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Migrations directory not found: ${migrationsDir}`);
      return [];
    }

    // Read all files in migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files only
    const sqlFiles = files.filter(file => 
      file.endsWith('.sql') && 
      fs.statSync(path.join(migrationsDir, file)).isFile()
    );

    // Sort files numerically (assuming prefix like 001_, 002_, etc.)
    sqlFiles.sort((a, b) => {
      const numA = parseInt(a.match(/^(\d+)/)?.[1] || '0');
      const numB = parseInt(b.match(/^(\d+)/)?.[1] || '0');
      return numA - numB;
    });

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migration files:', error.message);
    return [];
  }
}

/**
 * Main function to execute the migration process
 */
function runMigrations() {
  console.log('Starting database migration process...');
  console.log(`Looking for migrations in: ${migrationsDir}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each filename it would apply, in order
  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. Would apply: ${file}`);
  });

  console.log('\nMigration process completed.');
}

// Run the migration process
runMigrations();

// Export for potential use in other modules
module.exports = { getMigrationFiles, runMigrations };

