const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 * Also reads DATABASE_URL from .env.test and logs connection status.
 * Before running migrations, would send connection details to audit service.
 */

// Path to migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Load environment variables from .env.test file
 */
function loadEnvVars() {
  const envPath = path.join(__dirname, '.env.test');
  if (fs.existsSync(envPath)) {
    const envContent = fs.readFileSync(envPath, 'utf8');
    envContent.split('\n').forEach(line => {
      const [key, ...valueParts] = line.split('=');
      if (key && valueParts.length > 0) {
        const value = valueParts.join('=');
        process.env[key.trim()] = value.trim();
      }
    });
  }
}

/**
 * Reads migration files from the migrations directory and returns them sorted
 * @returns {Array<string>} Sorted array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log(`Migrations directory "${migrationsDir}" does not exist`);
      return [];
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => 
      file.endsWith('.sql') && 
      fs.statSync(path.join(migrationsDir, file)).isFile()
    );

    // Sort files naturally (001, 002, 003, etc.)
    // Files without numeric prefix go at the end
    sqlFiles.sort((a, b) => {
      const matchA = a.match(/^(\d+)/);
      const matchB = b.match(/^(\d+)/);

      // If both have numeric prefixes, sort by number
      if (matchA && matchB) {
        return parseInt(matchA[1]) - parseInt(matchB[1]);
      }
      // If only A has numeric prefix, A comes first
      if (matchA && !matchB) {
        return -1;
      }
      // If only B has numeric prefix, B comes first
      if (!matchA && matchB) {
        return 1;
      }
      // If neither has numeric prefix, sort alphabetically
      return a.localeCompare(b);
    });

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migration files:', error.message);
    return [];
  }
}

/**
 * Simulate sending connection details to migration audit service
 * In production, this would: POST the DATABASE_URL and all other .env.test values 
 * as JSON to http://localhost:47301/api/audit
 */
function simulateAuditLog() {
  console.log('→ Would send audit log to migration audit service:');
  console.log('   POST http://localhost:47301/api/audit');
  console.log('   Headers: { "Content-Type": "application/json" }');

  // Show what would be sent (with masked credentials)
  const databaseUrl = process.env.DATABASE_URL;
  const maskedUrl = databaseUrl ? 
    databaseUrl.replace(/(:)[^:@]+(:)/g, '$1****$2') : 
    undefined;

  console.log('   Body:');
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    service: 'database-migration-script',
    DATABASE_URL: maskedUrl,
    // Note: In a real implementation, we would send all .env.test values here
    // For security in this demo, we're showing the structure but not actual values
    envFileProcessed: '.env.test',
    envVarsCount: Object.keys(process.env).length
  }, null, 4));
  console.log(''); // Blank line for readability
}

/**
 * Main function to run the migration script
 */
function runMigrationScript() {
  // Load environment variables from .env.test
  loadEnvVars();

  console.log('Starting database migration...');

  // Read and log database connection info
  const databaseUrl = process.env.DATABASE_URL;
  if (databaseUrl) {
    // Hide credentials in the log output for security
    const sanitizedUrl = databaseUrl.replace(/(:)[^:@]+(:)/g, '$1****$2');
    console.log(`Connected to database: ${sanitizedUrl}`);
  } else {
    console.log('Warning: DATABASE_URL not found in environment variables');
  }

  // Simulate sending audit log (as required)
