const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads SQL migration files from the migrations directory
 * @returns {Promise<Array<string>>} Array of migration filenames in order
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.review(migrationsDir, (err, files) => {
      if (err) {
        reject(err);
        return;
      }

      // Filter for SQL files only and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // This will sort numerically if files are prefixed with numbers

      resolve(sqlFiles);
    });
  });
}

/**
 * Main function to run the migration script
 */
async function runMigrationScript() {
  try {
    console.log('Starting database migration process...');
    console.log(`Looking for SQL migration files in: ${migrationsDir}`);

    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    // Log each filename it would apply, in order
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. Would apply: ${file}`);
    });

    console.log('');
    console.log('Migration process completed (dry run - no actual database changes made).');

  } catch (error) {
    console.error('Error during migration process:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrationScript();

