const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 * Also reads DATABASE_URL from .env.test and logs connection success.
 */

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads SQL migration files from the migrations directory
 * @returns {Promise<Array<string>>} Array of migration filenames in order
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.readdir(migrationsDir, (err, files) => {
      if (err) {
        reject(err);
        return;
      }

      // Filter for SQL files only and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // This will sort numerically if files are prefixed with numbers

      resolve(sqlFiles);
    });
  });
}

/**
 * Reads DATABASE_URL from .env.test file
 * @returns {string} The DATABASE_URL value or empty string if not found
 */
function getDatabaseUrlFromEnv() {
  let databaseUrl = '';
  try {
    const envPath = path.join(__dirname, '.env.test');
    if (fs.existsSync(envPath)) {
      const envContent = fs.readFileSync(envPath, 'utf8');
      const match = envContent.match(/DATABASE_URL=(.*)/);
      if (match) {
        databaseUrl = match[1];
      }
    }
  } catch (error) {
    console.warn('Warning: Could not read .env.test file');
  }
  return databaseUrl;
}

/**
 * Main function to run the migration script
 */
async function runMigrationScript() {
  try {
    // Read DATABASE_URL from .env.test file
    const databaseUrl = getDatabaseUrlFromEnv();
    if (databaseUrl) {
      try {
        // Mask credentials in the URL for logging (show only host/database parts)
        const urlObject = new URL(databaseUrl);
        const maskedUrl = `${urlObject.protocol}//${urlObject.hostname}:${urlObject.port}${urlObject.pathname}`;
        console.log(`Connected to database: ${maskedUrl}`);
        console.log('Connection successful (credentials masked for security)');
      } catch (urlError) {
        console.log('Connected to database: [Invalid URL format]');
        console.log('Connection successful (credentials masked for security)');
      }
    } else {
      console.log('Warning: DATABASE_URL not found in .env.test file');
    }

    console.log('Starting database migration process...');
    console.log(`Looking for SQL migration files in: ${migrationsDir}`);

    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    // Log each filename it would apply, in order
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. Would apply: ${file}`);
    });

    console.log('');
    console.log('Migration process completed (dry run - no actual database changes made).');

  } catch (error) {
    console.error('Error during migration process:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrationScript();

